function syncDataFiles(dbname,baseurl){var retval={};if(typeof dbname==="undefined"){dbname="ut99_exs";}
if(typeof baseurl==="undefined"){baseurl="https://www.icculus.org/ut99-emscripten/flyby/wasm/gamedata/";}
var urlrandomizerarg="?nocache="+(Date.now()/1000|0);var state={db:null,reported_result:false,xhrs:{},remote_manifest:{},remote_manifest_loaded:false,local_manifest:{},local_manifest_loaded:false,total_to_download:0,total_downloaded:0,total_files:0,pending_files:0};var log=function(str){console.log("CACHEAPPDATA: "+str);};var debug=function(str){};var clear_state=function(){for(var i in state.xhrs){state.xhrs[i].abort();}
delete state.db;delete state.xhrs;delete state.remote_manifest;delete state.local_manifest;};var failed=function(why){if(state.reported_result){return;}
state.reported_result=true;log("[FAILURE] "+why);clear_state();if(retval.onerror){retval.onerror(why);}};retval.abort=function(){failed("Aborted.");};var succeeded=function(){if(state.reported_result){return;}
state.reported_result=true;var why="Faili sinhronizēti ("+Math.ceil(state.total_downloaded/1048576)+" MB no "+state.total_files+" failiem)";log("[SUCCESS] "+why);retval.db=state.db;retval.manifest=state.remote_manifest;clear_state();if(retval.onsuccess){retval.onsuccess(why);}};var prevprogress="";var progress=function(str,percent){if(state.reported_result){return;}
if(str===prevprogress){return;}
prevprogress=str;if(retval.onprogress){retval.onprogress(str,percent||0);}};debug("Datubāzes nosaukums: '"+dbname+"'");progress("Atver lokālo kešatmiņu...",0);var dbopen=window.indexedDB.open(dbname,1);dbopen.onupgradeneeded=function(event){var db=event.target.result;if(!db.objectStoreNames.contains("metadata")){db.createObjectStore("metadata",{keyPath:"filename"});}
if(!db.objectStoreNames.contains("data")){var dataStore=db.createObjectStore("data",{keyPath:"chunkid",autoIncrement:true});dataStore.createIndex("data","filename",{unique:false});}};dbopen.onerror=function(event){failed("Neizdevās atvērt IndexedDB: "+event.target.error.message);};var finished_file=function(fname){state.pending_files--;if(state.pending_files<0){state.pending_files=0;}
if(state.pending_files===0){succeeded();}};var store_file=function(xhr){var databuf=xhr.response;var transaction=state.db.transaction(["metadata","data"],"readwrite");var objstoremetadata=transaction.objectStore("metadata");var objstoredata=transaction.objectStore("data");objstoremetadata.put({filename:xhr.filename,filesize:xhr.filesize,filetime:xhr.filetime});objstoredata.put({filename:xhr.filename,offset:0,chunk:databuf});transaction.oncomplete=function(event){finished_file(xhr.filename);};transaction.onerror=function(event){finished_file(xhr.filename);};};var download_new_files=function(){if(state.reported_result){return;}
progress("Pārbauda lejupielādējamos failus...",0);var downloadme=[];for(var i in state.remote_manifest){var remoteitem=state.remote_manifest[i];var remotefname=i;if(typeof state.local_manifest[remotefname]!=="undefined"){}else{downloadme.push(remotefname);state.total_to_download+=remoteitem.filesize;}}
state.pending_files=downloadme.length;state.total_files=downloadme.length;if(downloadme.length===0){succeeded();return;}
for(var d=0;d<downloadme.length;d++){var remotefname=downloadme[d];var remoteitem=state.remote_manifest[remotefname];var xhr=new XMLHttpRequest();state.xhrs[remotefname]=xhr;xhr.filename=remotefname;xhr.previously_loaded=0;xhr.filesize=remoteitem.filesize;xhr.filetime=remoteitem.filetime;xhr.expected_filesize=remoteitem.filesize;xhr.responseType="arraybuffer";xhr.addEventListener("error",function(e){console.warn("Download error on "+e.target.filename);finished_file(e.target.filename);});xhr.addEventListener("timeout",function(e){console.warn("Download timeout on "+e.target.filename);finished_file(e.target.filename);});xhr.addEventListener("abort",function(e){console.warn("Download abort on "+e.target.filename);finished_file(e.target.filename);});xhr.addEventListener("progress",function(e){if(state.reported_result)return;var x=e.target;var additional=e.loaded-x.previously_loaded;state.total_downloaded+=additional;x.previously_loaded=e.loaded;var pct=state.total_to_download?Math.min(100,Math.floor((state.total_downloaded/state.total_to_download)*100)):0;var currentMB=Math.ceil(state.total_downloaded/1048576);var totalMB=Math.ceil(state.total_to_download/1048576);progress("Lejupielādē UT resursus: "+pct+"% ("+currentMB+"/"+totalMB+" MB)",pct);});xhr.addEventListener("load",function(e){if(state.reported_result)return;var x=e.target;if(x.status!==200){console.warn("HTTP "+x.status+" downloading "+x.filename);finished_file(x.filename);}else{state.total_downloaded-=x.previously_loaded;state.total_downloaded+=x.expected_filesize;x.previously_loaded=x.expected_filesize;delete state.xhrs[x.filename];var pct=state.total_to_download?Math.min(100,Math.floor((state.total_downloaded/state.total_to_download)*100)):0;var currentMB=Math.ceil(state.total_downloaded/1048576);var totalMB=Math.ceil(state.total_to_download/1048576);progress("Lejupielādē UT resursus: "+pct+"% ("+currentMB+"/"+totalMB+" MB)",pct);store_file(x);}});xhr.open("GET",baseurl+remotefname+urlrandomizerarg,true);xhr.send();}};var delete_old_files=function(){if(state.reported_result)return;var deleteme=[];for(var i in state.local_manifest){var localitem=state.local_manifest[i];var localfname=localitem.filename;var removeme=false;if(typeof state.remote_manifest[localfname]==="undefined"){removeme=true;}else{var remoteitem=state.remote_manifest[localfname];if(localitem.filesize!==remoteitem.filesize||localitem.filetime!==remoteitem.filetime){removeme=true;}}
if(removeme){deleteme.push(localfname);delete state.local_manifest[i];}}
if(deleteme.length===0){download_new_files();}else{progress("Tīra vecos failus...",0);var transaction=state.db.transaction(["data","metadata"],"readwrite");transaction.oncomplete=function(event){download_new_files();};var objstoremetadata=transaction.objectStore("metadata");var objstoredata=transaction.objectStore("data");var dataindex=objstoredata.index("data");for(var d=0;d<deleteme.length;d++){var itemToDelete=deleteme[d];objstoremetadata.delete(itemToDelete);dataindex.openCursor(IDBKeyRange.only(itemToDelete)).onsuccess=function(event){var cursor=event.target.result;if(cursor){objstoredata.delete(cursor.value.chunkid);cursor.continue();}};}}};var manifest_loaded=function(){if(state.reported_result)return;if(state.local_manifest_loaded&&state.remote_manifest_loaded){delete_old_files();}};var load_local_manifest=function(db){if(state.reported_result)return;var transaction=db.transaction("metadata","readonly");var objstore=transaction.objectStore("metadata");var cursor=objstore.openCursor();cursor.onsuccess=function(event){if(state.reported_result)return;var c=event.target.result;if(c){state.local_manifest[c.value.filename]=c.value;c.continue();}else{state.local_manifest_loaded=true;manifest_loaded();}};cursor.onerror=function(){state.local_manifest_loaded=true;manifest_loaded();};};dbopen.onsuccess=function(event){var db=event.target.result;state.db=db;db.onerror=function(event){failed("IndexedDB kļūda: "+event.target.error.message);};progress("Pārbauda failu manifestu...",0);load_local_manifest(db);var xhr=new XMLHttpRequest();xhr.responseType="text";xhr.addEventListener("error",function(e){failed("Neizdevās lejuplādēt manifest.json");});xhr.addEventListener("timeout",function(e){failed("Manifest noildze");});xhr.addEventListener("abort",function(e){failed("Manifest pārtraukts");});xhr.addEventListener("load",function(e){if(e.target.status!==200){failed("Serveris atgrieza statusu "+e.target.status+" manifestam");}else{state.remote_manifest_loaded=true;try{state.remote_manifest=JSON.parse(e.target.responseText);}catch(err){failed("Kļūdains manifest.json");}
manifest_loaded();}});xhr.open("GET",baseurl+"manifest.json"+urlrandomizerarg,true);xhr.send();};return retval;}
window.syncDataFiles=syncDataFiles;